import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Router } from '@angular/router';
import { OportunidadService, Oportunidad } from '../oportunidad.service';

interface Fase {
  titulo: string;
  etapas: number[];
  oportunidades: Oportunidad[];
  color: string;
}

@Component({
  selector: 'app-oportunidad-list',
  standalone: true,
  imports: [CommonModule, RouterModule],
  templateUrl: './oportunidad-list.component.html',
  styleUrls: ['./oportunidad-list.component.css'],
})
export class OportunidadListComponent implements OnInit {
  oportunidades: Oportunidad[] = [];
  fases: Fase[] = [
    { titulo: 'Fase 1: Prospecting', etapas: [1, 2, 3], oportunidades: [], color: '#3498db' },
    { titulo: 'Fase 2: Negotiation', etapas: [4, 5], oportunidades: [], color: '#f39c12' },
    { titulo: 'Fase 3: Closed', etapas: [6], oportunidades: [], color: '#27ae60' },
  ];
  loading = true;
  error = '';

  constructor(private oportunidadService: OportunidadService, private router: Router) {}

  ngOnInit() {
    this.cargarOportunidades();
  }

  cargarOportunidades() {
    this.loading = true;
    this.oportunidadService.listar().subscribe({
      next: (data) => {
        this.oportunidades = data;
        this.agruparPorFase();
        this.loading = false;
      },
      error: () => {
        this.error = 'Error al cargar oportunidades';
        this.loading = false;
      },
    });
  }

  agruparPorFase() {
    this.fases.forEach(fase => (fase.oportunidades = []));
    this.oportunidades.forEach(opp => {
      const fase = this.fases.find(f => f.etapas.includes(opp.id_etapa_oportunidad || 0));
      if (fase) fase.oportunidades.push(opp);
    });
  }

  cambiarEtapa(id: number, idFaseActual: number, direccion: 'siguiente' | 'anterior') {
    const faseActual = this.fases[idFaseActual];
    const faseNueva = direccion === 'siguiente' ? this.fases[idFaseActual + 1] : this.fases[idFaseActual - 1];
    if (!faseNueva) return;

    const idEtagaNueva = faseNueva.etapas[0];
    this.oportunidadService.cambiarEtapa(id, idEtagaNueva).subscribe({
      next: () => this.cargarOportunidades(),
      error: () => (this.error = 'Error al cambiar etapa'),
    });
  }

  crear() {
    this.router.navigate(['/oportunidades/nuevo']);
  }

  editar(id: number) {
    this.router.navigate(['/oportunidades', id, 'editar']);
  }

  eliminar(id: number) {
    if (confirm('¿Deseas eliminar esta oportunidad?')) {
      this.oportunidadService.eliminar(id).subscribe({
        next: () => this.cargarOportunidades(),
        error: () => (this.error = 'Error al eliminar oportunidad'),
      });
    }
  }

  ver(id: number) {
    this.router.navigate(['/oportunidades', id]);
  }
}
<div class="container">
  <div class="header">
    <h2>Oportunidades - Kanban</h2>
    <button class="btn btn-primary" (click)="crear()">+ Nueva Oportunidad</button>
  </div>
  <div *ngIf="error" class="alert alert-danger">{{ error }}</div>
  <div *ngIf="loading" class="loading">Cargando oportunidades...</div>
  <div *ngIf="!loading" class="kanban-board">
    <div *ngFor="let fase of fases; let i = index" class="kanban-column" [style.border-left-color]="fase.color">
      <div class="column-header" [style.background-color]="fase.color">
        <h3>{{ fase.titulo }}</h3>
        <span class="column-count">{{ fase.oportunidades.length }}</span>
      </div>
      <div class="cards-container">
        <div *ngIf="fase.oportunidades.length === 0" class="empty-column">
          Sin oportunidades
        </div>
        <div *ngFor="let opp of fase.oportunidades" class="card">
          <div class="card-header">
            <div class="card-number">{{ opp.numero_oportunidad }}</div>
            <div class="card-title">{{ opp.nombre_oportunidad }}</div>
          </div>
          <div class="card-body">
            <div class="card-row">
              <span class="label">Cliente ID:</span>
              <span class="value">{{ opp.id_cliente }}</span>
            </div>
            <div class="card-row">
              <span class="label">Monto:</span>
              <span class="value">{{ opp.monto_potencial | currency }}</span>
            </div>
          </div>
          <div class="card-actions">
            <button class="btn btn-sm btn-info" (click)="ver(opp.id_oportunidad!)">Ver</button>
            <button class="btn btn-sm btn-warning" (click)="editar(opp.id_oportunidad!)">Editar</button>
            <button class="btn btn-sm btn-danger" (click)="eliminar(opp.id_oportunidad!)">Eliminar</button>
          </div>
          <div class="card-navigation">
            <button
              *ngIf="i > 0"
              class="btn btn-sm btn-nav btn-prev"
              (click)="cambiarEtapa(opp.id_oportunidad!, i, 'anterior')"
              title="Mover a fase anterior">
              ← Anterior
            </button>
            <button
              *ngIf="i < fases.length - 1"
              class="btn btn-sm btn-nav btn-next"
              (click)="cambiarEtapa(opp.id_oportunidad!, i, 'siguiente')"
              title="Mover a fase siguiente">
              Siguiente →
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>
